(()=>{'use strict';
const $=id=>document.getElementById(id);
const PREFIX='archaea:v1:';
const seed=window.ARCHAEA_DATA||{issues:[]};
const safe=(x)=>String(x==null?'':x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const stamp=()=>new Date().toISOString();
const showDate=s=>{const d=String(s||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(d)?d:'待核验';};
const cap=(str,n=170)=>String(str||'').slice(0,n);
const doiUrl=(d)=>'https://doi.org/'+encodeURI(String(d||'').replace(/^https?:\/\/doi.org\//i,''));
function loadJSON(k,fallback){try{const x=localStorage.getItem(PREFIX+k);return x?JSON.parse(x):fallback;}catch(e){return fallback;}}
function saveJSON(k,obj){try{localStorage.setItem(PREFIX+k,JSON.stringify(obj));return true;}catch(e){toast('浏览器存储空间不足。请立即导出备份，或减少导入文件。');return false;}}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3200);}
const state={issueData:loadJSON('issues',seed.issues||[]),notes:loadJSON('notes',{}),margins:loadJSON('margins',{}),revisions:loadJSON('revisions',{}),pdfMeta:loadJSON('pdfmeta',{}),mode:'analysis',selected:null,issue:null,search:'',newest:true,editingMargin:null,mobile:'reader',historyOpen:false,readerUrl:null,loadingFulltext:false,tr:{},src:{},pdfPage:1,pdfView:'text',trcache:loadJSON('trcache',{})};
let saveTimer=null;let revisionTimer=null;let toastTimer=null;let lastSelection='';
const paperList=()=>state.issueData.flatMap(issue=>(issue.papers||[]).map(p=>({...p,__issue:issue.issue_id,__issueDate:issue.date})));
const noteFor=(key)=>state.notes[key]||{summary:'',methods:'',ideas:'',status:'unread',rating:'',updated:null};
const marginFor=(key)=>state.margins[key]||[];
function selectedPaper(){return paperList().find(p=>p.__issue===state.issue&&p.id===state.selected)||paperList().find(p=>p.id===state.selected)||null;}
function issueCode(issue){const n=Number(issue.issue_number);return 'NO.'+String(Number.isFinite(n)&&n>0?n:issue.date?.slice(-2)||'—').padStart(3,'0');}
function labels(p){return {title:p.title||'未命名论文',date:showDate(p.date),authors:Array.isArray(p.authors)?p.authors.join('、'):String(p.authors||''),journal:p.journal||'未收录期刊',kind:p.kind||'文献类型待核验',reading:p.reading_status||'来源批注未提供核读状态'};}
function activatePaper(id,issue){commitNote();state.selected=id;state.issue=issue||state.issue;state.mode='analysis';state.readerUrl=null;state.pdfPage=1;state.pdfView='text';state.historyOpen=false;try{localStorage.setItem(PREFIX+'active',JSON.stringify({id,issue:state.issue}));}catch(e){}render();setMobile('reader');$('centerCol').scrollTop=0;}
function normalizedIssues(){let a=[...state.issueData];a.sort((x,y)=>String(x.date).localeCompare(y.date)*(state.newest?-1:1));return a;}
function renderArchive(){const all=paperList(), text=state.search.trim().toLowerCase();const el=$('archiveList');let visible=0;el.innerHTML=normalizedIssues().map(issue=>{
 const ps=(issue.papers||[]).filter(p=>[p.title,p.doi,p.journal,p.question,[].concat(p.topic||[]).join(' ')].some(x=>String(x||'').toLowerCase().includes(text)));
 if(!ps.length)return '';visible+=ps.length;
 return `<div class="issue-group"><div class="issue-group-header"><span>${issueCode(issue)} · ${safe(issue.date)}</span><small>${ps.length} 篇</small></div>${ps.map((p,i)=>{
 const isactive=(p.id===state.selected&&issue.issue_id===state.issue);const note=noteFor(p.id);
 return `<button type="button" class="paper-item ${isactive?'active':''}" data-select="${safe(p.id)}" data-issue="${safe(issue.issue_id)}"><div class="small-number"><span>ARTICLE ${String(i+1).padStart(2,'0')}</span><span>${safe(p.priority||'A')}${note.status==='reviewed'?' · ✓ 已读':''}</span></div><div class="item-title">${safe(p.title)}</div><div class="item-meta"><span class="badge">${safe(p.journal||'ARTICLE')}</span> · ${safe(p.date||issue.date)}</div></button>`;
 }).join('')}</div>`;}).join('');
 if(!visible)el.innerHTML=`<div class="empty-search">没有匹配的文献。<br>试试作者、DOI 或研究主题。</div>`;
 $('totalPaperCount').textContent=`${all.length} 篇`;
 $('headerCount').textContent=`${state.issueData.length} ISSUES / ${all.length} PAPERS`;
}
function renderTitle(){const p=selectedPaper();if(!p){$('mainTitle').innerHTML='<h1 class="main-heading">还没有文献</h1>';return;}
 const l=labels(p);const n=noteFor(p.id);
 $('crumb').innerHTML=`ARCHIVE <span>/</span> ${safe(p.__issueDate)} <span>/</span> ${safe(p.doi||'未提供DOI')}`;
 $('mainTitle').innerHTML=`<div class="paper-date">${safe(p.__issueDate)} &nbsp; / &nbsp; ${safe(p.priority||'A')} · READING PRIORITY</div><h1 class="main-heading">${safe(l.title)}</h1><div class="main-meta">${safe(l.authors)}<br>${safe(l.journal)} · 首发 ${safe(l.date)} · ${safe(l.kind)}</div><div class="meta-chips"><span class="meta-chip">${safe(p.__issue)}</span>${p.doi?`<span class="meta-chip">DOI ${safe(p.doi)}</span>`:''}<span class="meta-chip copper">${safe(p.reading_status?'核读范围：'+p.reading_status:'核读范围待核验')}</span>${n.status==='reviewed'?'<span class="meta-chip">✓ 已精读</span>':''}</div>`;
}
function renderAnalysis(p){const sections=[['01 / RESEARCH QUESTION · 研究目标',p.question],['02 / MATERIALS · 研究材料',p.materials],['03 / STUDY DESIGN · 实验与研究设计',p.design],['04 / METHODS · 方法流程',p.methods],['05 / KEY FINDINGS · 关键结果',p.results],['06 / METHODOLOGICAL VALUE · 方法学创新',p.innovation],['07 / LIMITATIONS · 局限与竞争解释',p.limitations],['08 / FUTURE VALUE · 后续价值',p.future],['09 / LEARNING ROADMAP · 本科学习重点',p.learning]];
 const body=sections.map(([label,val])=>`<section class="section-block ${label.includes('LIMITATIONS')?'emphasis':''}"><div class="content-label">${safe(label)}</div><div class="content-body" data-selectable="yes">${safe(val||'本期原始归档未提供本部分的可核实详细信息。')}</div></section>`).join('');
 return `<div class="notice">归档说明：${safe(p.notice||'这是历史条目，请以原文为准。')} ${p.verification?'原档标注：'+safe(cap(p.verification,180)):''}</div><p class="main-intro">这里展示的是逐期保存的<strong>中文研究解读</strong>，不是论文原文。点击「原文阅读」可尝试查找合法开放获取全文。阅读原文后，你可以在右侧整理笔记，并将摘录归入左侧边注。</p><div class="link-row">${p.doi?`<a class="link-btn" target="_blank" rel="noopener noreferrer" href="${safe(doiUrl(p.doi))}">↗ 打开 DOI 原始来源</a>`:''}<button class="link-btn secondary" id="issueExportBtn">⤓ 导出当前论文 Markdown</button></div>${body}<div class="highlight-tip">✎ 选中中文精读中的一段文字，然后点击上方「选段批注」，即可在左侧保存引用与评论。出版社网页及跨域 PDF 无法直接由本站抓取鼠标选区。</div>`;
}
function renderMetadata(p){const l=labels(p);const rows=[['英文标题',l.title],['作者',l.authors],['期刊 / 平台',l.journal],['首次发表',l.date],['文献类型',l.kind],['DOI',p.doi||'未提供'],['收录期号',p.__issue],['核读程度',l.reading],['历史核验记录',p.verification||'未记录'],['来源提示',p.notice],['主题',Array.isArray(p.topic)?p.topic.join('、'):'']];
 return `<div class="notice info">此页保留了原归档提供的书目信息。过往“已核验”状态来自历史记录；需要重新确认时，请点击下方的在线核验按钮。</div><dl class="metadata-grid">${rows.map(([k,v])=>`<dt>${safe(k)}</dt><dd>${safe(v)}</dd>`).join('')}</dl><div class="link-row"><a class="link-btn" target="_blank" rel="noopener noreferrer" href="${safe(doiUrl(p.doi))}">↗ DOI 官方解析</a><button class="link-btn secondary" id="verifyDoiBtn">⌕ 在线核对 DOI 登记</button></div><div id="verificationResult"></div>`;
}
async function fetchPaperAbstract(p){if(!p||!p.doi)return '';let text='';try{const r=await fetch('https://api.openalex.org/works/https://doi.org/'+encodeURI(p.doi));if(r.ok){const j=await r.json();if(j&&j.abstract_inverted_index)text=abstractFromInverted(j.abstract_inverted_index);}}catch(e){}if(!text){try{const r=await fetch('https://api.crossref.org/works/'+encodeURIComponent(p.doi));if(r.ok){const j=await r.json();text=stripJats(j&&j.message&&j.message.abstract);}}catch(e){}}return String(text||'').trim();}
function splitSourceParagraphs(text){const clean=String(text||'').replace(/\r\n?/g,'\n').replace(/\u00a0/g,' ').trim();if(!clean)return [];const blocks=clean.split(/\n\s*\n+/).map(s=>s.trim()).filter(Boolean);if(blocks.length>1)return blocks;const sents=clean.match(/[^.!?;]+[.!?;]?["')\]]?\s*/g)||[clean];const out=[];let buf='';for(const s of sents){if((buf+s).length>260&&buf.trim()){out.push(buf.trim());buf='';}if(s.length>320){for(let i=0;i<s.length;i+=300)out.push(s.slice(i,i+300));}else{buf+=s;}}if(buf.trim())out.push(buf.trim());return out.length?out:[clean];}
/* ---------- 原文卡片：自动分段、自动翻译、词汇与内联批注 ---------- */
const TR_ENGINE_LABELS={auto:'自动（本地优先）',local:'Chrome 内置翻译',google:'Google 在线',api:'自定义 API'};
function trConfig(){const c=loadJSON('trcfg',{});return {engine:c.engine||'auto',base:c.base||'',model:c.model||'',key:c.key||''};}
function saveTrConfig(cfg){saveJSON('trcfg',cfg);}
function trHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return 'h'+(h>>>0).toString(36)+'_'+s.length;}
function trCacheGet(text){const c=state.trcache||{};const k=trHash(text);return c[k]&&c[k].t?c[k].t:'';}
function trCacheSet(text,val){state.trcache=state.trcache||{};state.trcache[trHash(text)]={t:val,at:Date.now()};const keys=Object.keys(state.trcache);if(keys.length>240){keys.sort((a,b)=>(state.trcache[a].at||0)-(state.trcache[b].at||0)).slice(0,keys.length-200).forEach(k=>delete state.trcache[k]);}saveJSON('trcache',state.trcache);}
async function translateWithApi(text,cfg){const base=String(cfg.base||'').replace(/\/+$/,'');if(!base)throw Error('未填写 API 地址');const r=await fetch(base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+cfg.key},body:JSON.stringify({model:cfg.model||'deepseek-chat',temperature:0,messages:[{role:'system',content:'You are a precise academic translator. Translate the user text into Simplified Chinese. Output only the translation, no notes.'},{role:'user',content:text}]})});if(!r.ok)throw Error('API HTTP '+r.status);const j=await r.json();const out=j&&j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content;if(!out)throw Error('API 无译文');return String(out).trim();}
async function translateSmart(text){const cfg=trConfig();const cached=trCacheGet(text);if(cached)return cached;let out='';if(cfg.engine==='api'&&cfg.key&&cfg.base){out=await translateWithApi(text,cfg);}else{if(cfg.engine!=='google'){const local=await getLocalTranslator();if(local){try{out=await local.translate(text);}catch(e){if(cfg.engine==='local')throw e;}}}if(!out){if(cfg.engine==='local')throw Error('浏览器内置翻译不可用');out=await remoteTranslate(text);}}if(!out)throw Error('没有译文');trCacheSet(text,out);return out;}
let srcTrQueue=[],srcTrActive=0,srcObserver=null;
function queueSourceTranslation(p,idx){const rec=state.src[p.id];if(!rec||!rec.paragraphs||!rec.paragraphs[idx])return;if(rec.translations&&rec.translations[idx])return;const key=p.id+'#'+rec.gen+'#'+idx;if(srcTrQueue.some(j=>j.key===key))return;srcTrQueue.push({key,p,idx,rec,gen:rec.gen});pumpSourceTranslations();}
function pumpSourceTranslations(){while(srcTrActive<2&&srcTrQueue.length){const job=srcTrQueue.shift();srcTrActive++;ensureSourceTranslation(job).finally(()=>{srcTrActive--;pumpSourceTranslations();});}}
async function ensureSourceTranslation(job){const {p,idx,rec,gen}=job;if(state.src[p.id]!==rec||rec.gen!==gen)return;const text=rec.paragraphs[idx];const el=document.querySelector('.src-para[data-src-index="'+idx+'"] .src-zh');if(el&&!el.dataset.done){el.textContent='翻译中…';el.classList.add('muted');}try{const out=await translateSmart(text);if(state.src[p.id]!==rec||rec.gen!==gen)return;rec.translations=rec.translations||{};rec.translations[idx]=out;if(el){el.textContent=out;el.classList.remove('muted','error');el.dataset.done='1';}updateSourceTrStatus(p);}catch(e){if(el){el.textContent='翻译失败：'+(e&&e.message?e.message:e);el.classList.add('error');el.classList.remove('muted');}updateSourceTrStatus(p);}}
function updateSourceTrStatus(p){const el=$('srcTrStatus');const rec=state.src[p.id];if(!el||!rec)return;const total=rec.paragraphs.length;const done=Object.keys(rec.translations||{}).length;el.textContent='译文 '+done+'/'+total;}
function applySourceText(p,text,label){const prev=state.src[p.id];state.src[p.id]={text,label,paragraphs:splitSourceParagraphs(text),translations:{},gen:((prev&&prev.gen)||0)+1};renderMain();const panel=document.querySelector('.src-panel');if(panel&&panel.scrollIntoView)panel.scrollIntoView({block:'nearest'});}
function enhanceSourceReader(p){const rec=state.src[p.id];if(!rec||!rec.paragraphs||!rec.paragraphs.length)return;ensureReaderSettings(p);document.querySelectorAll('.src-para[data-src-index]').forEach(el=>{if(el.dataset.enhanced)return;el.dataset.enhanced='1';const idx=Number(el.dataset.srcIndex);const text=rec.paragraphs[idx]||'';const zh=el.querySelector('.src-zh');if(zh){const cached=(rec.translations&&rec.translations[idx])||trCacheGet(text);if(cached){zh.textContent=cached;zh.dataset.done='1';rec.translations=rec.translations||{};rec.translations[idx]=cached;}else{zh.textContent='翻译中…';zh.classList.add('muted');}}const vocab=analyzeVocabulary(text).filter(v=>v.tag!=='未收录').slice(0,6);const vw=el.querySelector('.src-vocab');if(vw&&vocab.length){vw.innerHTML=vocab.map(v=>'<span class="vitem"><span class="vchip lv-'+safe(v.cls)+'">'+safe(v.tag)+'</span><b>'+safe(v.word)+'</b> '+safe(v.zh)+'</span>').join('');}fillBlockMargins(p,idx);});if(srcObserver)srcObserver.disconnect();srcObserver=new IntersectionObserver(entries=>{entries.forEach(en=>{if(en.isIntersecting){queueSourceTranslation(p,Number(en.target.dataset.srcIndex));srcObserver.unobserve(en.target);}});},{root:$('centerCol'),rootMargin:'250px'});document.querySelectorAll('.src-para[data-src-index]').forEach(el=>srcObserver.observe(el));[0,1,2].forEach(i=>{if(rec.paragraphs[i])queueSourceTranslation(p,i);});updateSourceTrStatus(p);}
function ensureReaderSettings(p){const panel=document.querySelector('.src-panel');if(!panel||panel.querySelector('.src-settings'))return;const cfg=trConfig();const box=document.createElement('details');box.className='src-settings';box.innerHTML='<summary>翻译设置：'+safe(TR_ENGINE_LABELS[cfg.engine]||'自动（本地优先）')+'</summary><div class="src-settings-body"><label>引擎 <select data-tr-engine><option value="auto">自动（本地优先，失败转在线）</option><option value="local">Chrome 内置翻译</option><option value="google">Google 在线</option><option value="api">自定义 API</option></select></label><div class="src-api-fields'+(cfg.engine==='api'?'':' hidden')+'" data-tr-api><label>API 地址 <input data-tr-base placeholder="https://api.deepseek.com/v1" value="'+safe(cfg.base)+'"></label><label>模型 <input data-tr-model placeholder="deepseek-chat" value="'+safe(cfg.model)+'"></label><label>API Key <input type="password" data-tr-key placeholder="只保存在本机" value="'+safe(cfg.key)+'"></label></div><div class="src-settings-actions"><button type="button" class="link-btn" data-tr-save>保存设置</button><span class="src-hint" id="srcTrStatus"></span></div></div>';panel.appendChild(box);box.querySelector('[data-tr-engine]').value=cfg.engine;}
function saveReaderSettings(){const box=document.querySelector('.src-settings');if(!box)return;const cfg={engine:box.querySelector('[data-tr-engine]').value,base:box.querySelector('[data-tr-base]').value.trim(),model:box.querySelector('[data-tr-model]').value.trim(),key:box.querySelector('[data-tr-key]').value.trim()};saveTrConfig(cfg);const sum=box.querySelector('summary');if(sum)sum.textContent='翻译设置：'+(TR_ENGINE_LABELS[cfg.engine]||'自动（本地优先）');const p=selectedPaper();if(p){const rec=state.src[p.id];if(rec&&rec.paragraphs){rec.translations={};rec.gen++;document.querySelectorAll('.src-zh').forEach(z=>{z.textContent='';z.classList.remove('error','muted');delete z.dataset.done;});document.querySelectorAll('.src-para[data-src-index]').forEach(el=>queueSourceTranslation(p,Number(el.dataset.srcIndex)));}}toast('翻译设置已保存，正在用新引擎重译');}
function toggleSourceComposer(btn){if(!btn)return;const block=btn.closest('.src-para');if(!block)return;const c=block.querySelector('.src-compose');if(!c)return;const open=c.classList.contains('hidden');document.querySelectorAll('.src-compose').forEach(x=>x.classList.add('hidden'));if(open){c.classList.remove('hidden');const ta=c.querySelector('textarea');if(ta){ta.focus();ta.scrollIntoView({block:'nearest'});}}}
function hideSourceComposer(btn){const c=btn.closest('.src-compose');if(c)c.classList.add('hidden');}
function fillBlockMargins(p,idx){const block=document.querySelector('.src-para[data-src-index="'+idx+'"]');if(!block||!p)return;const loc=block.dataset.locator;const ms=marginFor(p.id).filter(m=>m.locator===loc);const wrap=block.querySelector('.src-margins');if(wrap){wrap.innerHTML=ms.map(m=>'<div class="src-margin"><span class="src-margin-kind">'+safe(MARGIN_LABELS[m.kind]||'边注')+'</span><p>'+safe(m.comment||m.quote)+'</p><button type="button" data-del-annotation="'+safe(m.id)+'" title="删除这条边注">×</button></div>').join('');}const badge=block.querySelector('.src-para-badge');if(badge){badge.textContent=ms.length?'✎ '+ms.length:'';badge.style.display=ms.length?'inline':'none';}block.classList.toggle('annotated',ms.length>0);}
function saveInlineAnnotation(p,idx){if(!p)return;const rec=state.src[p.id];const block=document.querySelector('.src-para[data-src-index="'+idx+'"]');if(!rec||!block||!rec.paragraphs[idx])return;const ta=block.querySelector('.src-compose textarea');const comment=ta?ta.value.trim():'';if(!comment)return toast('请先写批注');const arr=state.margins[p.id]||(state.margins[p.id]=[]);arr.push({id:stamp()+'_'+Math.random().toString(36).slice(2,7),quote:rec.paragraphs[idx],comment,locator:block.dataset.locator,kind:'question',updated:stamp()});saveJSON('margins',state.margins);renderMargins();fillBlockMargins(p,idx);const c=block.querySelector('.src-compose');if(c)c.classList.add('hidden');toast('边注已保存到左侧');}
function deleteInlineMargin(p,id){if(!p||!id)return;const block=[...document.querySelectorAll('.src-para')].find(b=>b.querySelector('[data-del-annotation="'+id+'"]'));state.margins[p.id]=marginFor(p.id).filter(m=>m.id!==id);saveJSON('margins',state.margins);renderMargins();if(block)fillBlockMargins(p,Number(block.dataset.srcIndex));toast('边注已删除');}
/* ---------- PDF 文本抽取：自动分页 / 分栏 / 分段（pdf.js） ---------- */
let pdfjsPromise=null;
async function loadPdfjs(){if(pdfjsPromise)return pdfjsPromise;pdfjsPromise=(async()=>{const mod=await import('./vendor/pdf.min.mjs');mod.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.min.mjs';return mod;})().catch(e=>{pdfjsPromise=null;throw e;});return pdfjsPromise;}
function pdfMedian(arr){if(!arr.length)return 0;const s=[...arr].sort((a,b)=>a-b);const m=s.length>>1;return s.length%2?s[m]:(s[m-1]+s[m])/2;}
function spansToLines(spans){spans.sort((a,b)=>a.y-b.y||a.x-b.x);const lines=[];let cur=null;const flush=()=>{if(!cur)return;const g=cur.spans.sort((a,b)=>a.x-b.x);let text='';let prev=null;for(const s of g){if(prev){const gap=s.x-(prev.x+prev.width);const tol=Math.max(1,Math.min(prev.height,s.height)*0.18);if(gap>tol&&!/[-‐‑]$/.test(prev.text)&&!/^[,.;:!?%)\]}]/.test(s.text))text+=' ';}text+=s.text;prev=s;}const x=Math.min(...g.map(s=>s.x));const right=Math.max(...g.map(s=>s.x+s.width));lines.push({text:text.replace(/\s+/g,' ').trim(),x,y:cur.y,width:right-x,height:cur.h});cur=null;};for(const s of spans){if(!cur){cur={spans:[s],y:s.y,h:s.height,minX:s.x,maxX:s.x+s.width};continue;}const tolY=Math.max(2,Math.min(cur.h,s.height)*0.45);const gapX=s.x>cur.maxX?s.x-cur.maxX:(cur.minX-(s.x+s.width));if(Math.abs(s.y-cur.y)<=tolY&&gapX<=Math.max(14,Math.min(cur.h,s.height)*1.6)){cur.spans.push(s);cur.h=Math.max(cur.h,s.height);cur.minX=Math.min(cur.minX,s.x);cur.maxX=Math.max(cur.maxX,s.x+s.width);}else{flush();cur={spans:[s],y:s.y,h:s.height,minX:s.x,maxX:s.x+s.width};}}flush();return lines.filter(l=>l.text);}
function pdfLinesFromItems(items,pageHeight){const spans=[];for(const it of items||[]){if(!it||!it.str||!it.str.trim())continue;const tr=it.transform||[1,0,0,1,0,0];const h=Math.abs(it.height)||Math.abs(tr[3])||10;spans.push({text:it.str,x:tr[4],y:pageHeight-tr[5]-h,width:Math.max(0,it.width||0),height:h});}return spansToLines(spans);}
function joinPdfLines(lines){let t='';for(const l of lines){if(!t){t=l.text;continue;}if(/[-‐‑]$/.test(t))t=t.slice(0,-1)+l.text;else t+=' '+l.text;}return t.replace(/\s+/g,' ').trim();}
function pdfBlocksFromLines(lines,viewport){if(!lines.length)return [];const W=viewport.width,mid=W/2;const med=pdfMedian(lines.map(l=>l.height))||10;const narrow=lines.filter(l=>l.width<W*0.55);const rightN=narrow.filter(l=>l.x+l.width/2>=mid);const leftN=narrow.filter(l=>l.x+l.width/2<mid);const two=leftN.length>=4&&rightN.length>=4;const columnTop=two?Math.min(...rightN.map(l=>l.y)):Infinity;const assigned=lines.map(l=>{let col;if(!two)col='full';else if(l.y<columnTop-2)col='full';else if(l.width>W*0.55)col='full';else if(l.height<med*0.82&&l.width>W*0.3)col='full';else col=((l.x+l.width/2)<mid?'left':'right');return {...l,column:col};});let ordered;if(!two){ordered=assigned.slice().sort((a,b)=>a.y-b.y||a.x-b.x);}else{const non=assigned.filter(l=>l.column!=='full');const topY=Math.min(...non.map(l=>l.y));const bottomY=Math.max(...non.map(l=>l.y+l.height));const before=assigned.filter(l=>l.column==='full'&&l.y<topY);const after=assigned.filter(l=>l.column==='full'&&l.y>=bottomY);const left=assigned.filter(l=>l.column==='left').sort((a,b)=>a.y-b.y);const right=assigned.filter(l=>l.column==='right').sort((a,b)=>a.y-b.y);const embedded=assigned.filter(l=>l.column==='full'&&!before.includes(l)&&!after.includes(l));ordered=[...before.sort((a,b)=>a.y-b.y),...left,...right,...embedded.sort((a,b)=>a.y-b.y),...after.sort((a,b)=>a.y-b.y)];}const blocks=[];let cur=null;const finish=()=>{if(!cur)return;const text=joinPdfLines(cur.lines);if(text){const x=Math.min(...cur.lines.map(l=>l.x));const right=Math.max(...cur.lines.map(l=>l.x+l.width));blocks.push({text,x,y:Math.min(...cur.lines.map(l=>l.y)),width:right-x,height:Math.max(...cur.lines.map(l=>l.y+l.height))-Math.min(...cur.lines.map(l=>l.y)),column:cur.column});}cur=null;};for(const line of ordered){if(!cur){cur={lines:[line],column:line.column};continue;}const prev=cur.lines[cur.lines.length-1];const gap=line.y-(prev.y+prev.height);const same=line.column===cur.column;const indent=line.x>prev.x+med*0.9;const end=/[.!?。！？:：]$/.test(prev.text);if(!same||gap>med*1.9||(indent&&gap>med*1.1)){finish();cur={lines:[line],column:line.column};}else cur.lines.push(line);}finish();return blocks.filter(b=>b.text.length>=2&&!/^[-–—\s]*\d{1,4}[-–—\s]*$/.test(b.text));}
let ocrScriptPromise=null,ocrWorkerPromise=null;
function loadTesseractScript(){if(ocrScriptPromise)return ocrScriptPromise;ocrScriptPromise=new Promise((res,rej)=>{if(window.Tesseract){res();return;}const s=document.createElement('script');s.src='./vendor/tesseract/tesseract.min.js';s.onload=()=>res();s.onerror=()=>{ocrScriptPromise=null;rej(Error('OCR 脚本加载失败'));};document.head.appendChild(s);});return ocrScriptPromise;}
async function getOcrWorker(onStatus){if(ocrWorkerPromise)return ocrWorkerPromise;ocrWorkerPromise=(async()=>{await loadTesseractScript();return await window.Tesseract.createWorker('eng',1,{workerPath:'./vendor/tesseract/worker.min.js',corePath:'./vendor/tesseract/',langPath:'./vendor/tesseract/',workerBlobURL:false,logger:m=>{if(m&&m.status&&onStatus)onStatus('OCR：'+m.status,m.progress);}});})();return ocrWorkerPromise;}
async function terminateOcr(){if(!ocrWorkerPromise)return;try{const w=await ocrWorkerPromise;await w.terminate();}catch(e){}ocrWorkerPromise=null;}
function ocrBlocksToPdfBlocks(data){const out=[];const blocks=data&&data.blocks;if(Array.isArray(blocks)){for(const b of blocks){for(const p of (b.paragraphs||[])){const t=(p.lines||[]).map(l=>l.text||'').join(' ').replace(/\s+/g,' ').trim();if(t.length>1)out.push({text:t,x:0,y:out.length*12,width:0,height:12,column:'full'});}}}if(out.length)return out;const text=String(data&&data.text||'').replace(/\r/g,'');const paras=text.split(/\n\s*\n+/).map(s=>s.replace(/\s+/g,' ').trim()).filter(Boolean);if(paras.length>1)return paras.map((t,i)=>({text:t,x:0,y:i*12,width:0,height:12,column:'full'}));return splitSourceParagraphs(text).map((t,i)=>({text:t,x:0,y:i*12,width:0,height:12,column:'full'}));}
function ocrTsvToBlocks(tsv,vp){const groups=new Map();for(const row of String(tsv||'').split(/\r?\n/)){const cols=row.split('\t');if(cols.length<12||cols[0]!=='5')continue;const text=cols.slice(11).join('\t').trim();if(!text)continue;const key=cols[2]+'-'+cols[3]+'-'+cols[4];const left=Number(cols[6]),top=Number(cols[7]),w=Number(cols[8])||1,h=Number(cols[9])||1;if(!Number.isFinite(left)||!Number.isFinite(top))continue;let g=groups.get(key);if(!g){g=[];groups.set(key,g);}g.push({text,left,top,w,h});}if(!groups.size)return null;const gapLimit=Math.max(18,vp.width*0.025);const lines=[];for(const words of groups.values()){words.sort((a,b)=>a.left-b.left);let seg=[];let lastRight=null;const pushSeg=()=>{if(!seg.length)return;const minX=Math.min(...seg.map(w=>w.left));const maxX=Math.max(...seg.map(w=>w.left+w.w));const minY=Math.min(...seg.map(w=>w.top));const maxY=Math.max(...seg.map(w=>w.top+w.h));lines.push({text:seg.map(w=>w.text).join(' '),x:minX,y:minY,width:Math.max(1,maxX-minX),height:Math.max(1,maxY-minY)});seg=[];lastRight=null;};for(const w of words){if(lastRight!==null&&w.left-lastRight>gapLimit)pushSeg();seg.push(w);lastRight=w.left+w.w;}pushSeg();}return pdfBlocksFromLines(lines,{width:vp.width,height:vp.height});}
function ocrWordsToPdfBlocks(data,vp){const words=(data&&data.words||[]).filter(w=>w&&w.text&&String(w.text).trim()&&w.bbox);if(!words.length)return null;const spans=words.map(w=>({text:String(w.text),x:w.bbox.x0,y:w.bbox.y0,width:Math.max(1,w.bbox.x1-w.bbox.x0),height:Math.max(1,w.bbox.y1-w.bbox.y0)}));const lines=spansToLines(spans);return pdfBlocksFromLines(lines,{width:vp.width,height:vp.height});}
async function ocrPdfPage(page,onStatus){const worker=await getOcrWorker(onStatus);const vp=page.getViewport({scale:2});const canvas=document.createElement('canvas');canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);const ctx=canvas.getContext('2d',{willReadFrequently:true});await page.render({canvasContext:ctx,viewport:vp}).promise;const res=await worker.recognize(canvas,{}, {text:true,blocks:true,tsv:true});const data=(res&&res.data)?res.data:res;canvas.width=0;canvas.height=0;const byTsv=ocrTsvToBlocks(data.tsv,vp);if(byTsv&&byTsv.length)return byTsv;const byWords=ocrWordsToPdfBlocks(data,vp);if(byWords&&byWords.length)return byWords;return ocrBlocksToPdfBlocks(data);}
async function extractPdfPages(data,onProgress,onStatus){const pdfjs=await loadPdfjs();const src=(typeof data==='string')?{url:data}:{data:(data instanceof ArrayBuffer)?new Uint8Array(data):data};const doc=await pdfjs.getDocument(src).promise;const pages=[];let ocrUsed=false;try{for(let n=1;n<=doc.numPages;n++){const page=await doc.getPage(n);const vp=page.getViewport({scale:1});const content=await page.getTextContent();const lines=pdfLinesFromItems(content.items,vp.height);let blocks=pdfBlocksFromLines(lines,vp);const chars=blocks.reduce((a,b)=>a+b.text.length,0);if(chars<40){if(onStatus)onStatus('第 '+n+' 页没有文本层，OCR 识别中（较慢）…');try{const ob=await ocrPdfPage(page,onStatus);if(ob.length){blocks=ob;ocrUsed=true;}}catch(e){console.warn('OCR failed',e);}}pages.push({num:n,width:vp.width,height:vp.height,blocks});if(onProgress)onProgress(n,doc.numPages);}}finally{if(ocrWorkerPromise)await terminateOcr();try{await doc.destroy();}catch(e){}}return {pages};}
function applyPdfSource(p,data,label){const paragraphs=[],locs=[],pageOf=[];let inRefs=false;for(const page of data.pages){let idx=0;for(const b of page.blocks){const text=String(b.text||'').trim();if(!text)continue;if(/^(references|bibliography|参考文献)\s*$/i.test(text)||(text.length<60&&/^(references|bibliography|参考文献)\b/i.test(text))){inRefs=true;continue;}if(inRefs)continue;if(text.length<18&&/^\d+$/.test(text))continue;if(/^(provided proper attribution|copyright|©|arxiv:|preprint|downloaded from|all rights reserved|this article is|open access)/i.test(text))continue;if(/@/.test(text)&&text.length<300)continue;if(/^[∗†‡]/.test(text))continue;if(/^(abstract|摘要)\s*$/i.test(text))continue;const letters=(text.match(/[A-Za-z\u4e00-\u9fff]/g)||[]).length;if(text.length>25&&letters/text.length<0.45)continue;paragraphs.push(text);locs.push('PDF p.'+page.num+' ¶'+(++idx));pageOf.push(page.num);}}if(!paragraphs.length)throw Error('没有提取到文本');const prev=state.src[p.id];state.src[p.id]={kind:'pdf',label:label||'PDF',text:paragraphs.join('\n\n'),paragraphs,locs,pageOf,translations:{},gen:((prev&&prev.gen)||0)+1,pages:data.pages.length};state.pdfView='text';renderMain();}
async function extractAndShowPdf(p,data,label){const setStatus=t=>{const s=$('originalStatus');if(s)s.textContent=t;};setStatus('正在解析 PDF 文本…');try{const extracted=await extractPdfPages(data,(n,total)=>setStatus('正在解析 PDF：第 '+n+'/'+total+' 页…'),(msg,pct)=>setStatus(msg+(pct?(' '+Math.round(pct*100)+'%'):'')));let chars=0;for(const pg of extracted.pages)for(const b of pg.blocks)chars+=b.text.length;if(chars<60)throw Error('没有文本层（可能是扫描版）');applyPdfSource(p,extracted,label);toast('已识别 '+extracted.pages.length+' 页，自动分段并开始翻译');}catch(e){console.error('PDF extract failed',e&&e.stack||e);state.pdfView='frame';renderMain();setStatus('PDF 文本解析失败：'+(e&&e.message?e.message:e)+'。已保留原 PDF 预览。');toast('PDF 解析失败，已保留原 PDF 预览');}}
function renderSourcePanel(p){const rec=state.src[p.id];const head='<div class="src-head"><h3>原文对照阅读</h3><span>原文 · 译文 · 词汇自动生成；点击段落即可写批注</span></div>';const paste='<div class="src-paste hidden" id="srcPasteWrap"><textarea id="srcPaste" spellcheck="false" placeholder="粘贴原文或摘要，空行分段；单段长文本会按句子自动切分。"></textarea><div class="link-row"><button class="link-btn" id="segmentSrc">开始阅读</button><button class="bare-btn" id="cancelSrcPaste">取消</button></div></div>';if(!rec||!rec.paragraphs||!rec.paragraphs.length){return '<section class="src-panel">'+head+'<div class="src-actions"><button class="link-btn secondary" id="loadSrcAbstract">↧ 载入开放摘要</button><button class="link-btn secondary" id="showSrcPaste">✎ 粘贴原文</button><span class="src-hint">PDF 文字若无法直接读取，可从 PDF 复制后粘贴到这里。</span></div>'+paste+'</section>';}const margins=marginFor(p.id);const paras=rec.paragraphs.map((txt,i)=>{const loc=(rec.locs&&rec.locs[i])||((rec.label||'原文')+' ¶'+(i+1));const pg=rec.pageOf&&rec.pageOf[i];const marker=(pg&&(i===0||rec.pageOf[i-1]!==pg))?'<div class="pdf-page-marker">第 '+pg+' 页</div>':'';const n=margins.filter(m=>m.locator===loc).length;return marker+'<div class="src-para'+(n?' annotated':'')+'" data-src-index="'+i+'" data-locator="'+safe(loc)+'"><div class="src-para-head"><span class="src-para-no">¶'+(i+1)+'</span><span class="src-para-tools"><span class="src-para-badge"'+(n?'':' style="display:none"')+'>'+(n?'✎ '+n:'')+'</span><button type="button" class="src-annot-btn" data-annotate="'+i+'">＋ 批注</button></span></div><div class="src-para-text">'+safe(txt)+'</div><div class="src-zh" data-zh="'+i+'"></div><div class="src-vocab" data-vocab="'+i+'"></div><div class="src-margins" data-margins="'+i+'"></div><div class="src-compose hidden" data-compose="'+i+'"><textarea placeholder="写下你的批注……"></textarea><div class="src-compose-actions"><button type="button" class="link-btn" data-save-annotation="'+i+'">保存批注</button><button type="button" class="bare-btn" data-cancel-annotation="'+i+'">取消</button></div></div></div>';}).join('');return '<section class="src-panel">'+head+'<div class="src-actions"><button class="link-btn secondary" id="loadSrcAbstract">↧ 重新载入摘要</button><button class="link-btn secondary" id="showSrcPaste">✎ 换一段原文</button><span class="src-hint">'+(rec.label||'原文')+' · '+rec.paragraphs.length+' 段 · 点击段落即可批注</span></div>'+paste+'<div class="src-paras">'+paras+'</div></section>';}
function renderOriginal(p){
 const rec=state.src[p.id];
 const hasText=!!(rec&&rec.kind==='pdf');
 const showFrame=!!state.readerUrl&&state.pdfView==='frame';
 const pagebar=showFrame?'<div class="pdf-pagebar" id="pdfPageBar"><button type="button" class="page-btn" data-pdfpage="-1" title="上一页">◀</button><span class="page-ind">第 <b id="pdfPageNum">'+(state.pdfPage||1)+'</b> 页</span><button type="button" class="page-btn" data-pdfpage="1" title="下一页">▶</button><button type="button" class="link-btn secondary" id="annotatePdfPage">＋ 批注本页</button><span class="page-hint" id="pdfPageHint"></span></div>':'';
 const toggle=(state.readerUrl&&(hasText||showFrame))?'<div class="pdf-textbar"><span>'+(hasText?'已提取文字阅读':'已载入原 PDF')+'</span><button type="button" class="link-btn secondary" id="togglePdfView">'+(showFrame?'返回文字阅读':'查看原 PDF')+'</button></div>':'';
 const frame=showFrame?'<iframe class="pdf-frame" src="'+safe(state.readerUrl+(state.pdfPage>1?'#page='+state.pdfPage:''))+'" title="PDF 原文" referrerpolicy="no-referrer"></iframe>':(hasText?'':'<div class="blank-frame"><div><strong>READ THE SOURCE</strong>点击「查找开放获取原文」或「载入本机 PDF」，进入原文阅读。<br>DOI 本身并不保证论文全文开放获取。</div></div>');
 return '<div class="notice info">合法全文优先：载入本机 PDF 或抓取开放获取 PDF 后，会优先<strong>自动提取文字、按页分栏分段</strong>，并对每段生成译文与词汇；PDF 无法解析时保留原样预览，也可把文字粘贴到下方。</div><div class="original-toolbar"><div class="link-row"><button class="link-btn" id="findOA">⌕ 查找开放获取原文</button><button class="link-btn secondary" id="localPdfBtn">＋ 载入本机 PDF</button><a class="link-btn secondary" href="'+safe(doiUrl(p.doi))+'" target="_blank" rel="noopener noreferrer">↗ 出版社 / DOI</a></div></div><div class="original-hint" id="originalStatus">载入 PDF 后自动识别文字并分页；扫描版会尝试 OCR（较慢）。无法读取时可用下方「粘贴原文」。</div>'+pagebar+toggle+'<div id="originalFrame">'+frame+'</div>'+renderSourcePanel(p);
}
async function loadSourceAbstract(){const p=selectedPaper();if(!p)return;if(!p.doi)return toast('本篇没有 DOI，无法自动获取摘要');const st=$('originalStatus');if(st)st.textContent='正在从 OpenAlex / Crossref 获取开放摘要…';const text=await fetchPaperAbstract(p);if(!text){if(st)st.textContent='没有取到开放摘要。可从 PDF 复制文本，用「粘贴原文」分段。';return toast('没有取到开放摘要');}applySourceText(p,text,'摘要');toast('已自动分段，正在逐段翻译');}
function toggleSrcPaste(force){const w=$('srcPasteWrap');if(!w)return;const show=force===undefined?w.classList.contains('hidden'):!!force;w.classList.toggle('hidden',!show);if(show){const ta=$('srcPaste');if(ta)ta.focus();}}
function segmentSrcText(){const p=selectedPaper();if(!p)return;const ta=$('srcPaste');const text=ta?ta.value.trim():'';if(!text)return toast('请先粘贴原文');applySourceText(p,text,'原文');toast('已自动分段，正在逐段翻译');}
function updatePdfPageUI(){const p=selectedPaper();const n=state.pdfPage||1;const num=$('pdfPageNum');if(num)num.textContent=n;const hint=$('pdfPageHint');if(hint&&p){const c=marginFor(p.id).filter(m=>m.locator==='PDF p.'+n).length;hint.textContent=c?'本页已有 '+c+' 条边注':'翻页后点「批注本页」';}}
function pdfGo(delta){state.pdfPage=Math.max(1,(state.pdfPage||1)+delta);const fr=document.querySelector('#originalFrame iframe');if(fr&&state.readerUrl){const base=String(state.readerUrl).split('#')[0];fr.src=base+'#page='+state.pdfPage;}updatePdfPageUI();}
function annotatePdfPage(){const p=selectedPaper();if(!p)return;if(!state.readerUrl)return toast('请先载入 PDF 或开放原文');openMargin(null,'','PDF p.'+(state.pdfPage||1));}
function refreshSrcBadges(){const p=selectedPaper();if(!p)return;const rec=state.src[p.id];if(!rec)return;const margins=marginFor(p.id);document.querySelectorAll('.src-para[data-locator]').forEach(el=>{const n=margins.filter(m=>m.locator===el.dataset.locator).length;let b=el.querySelector('.src-para-badge');if(n>0){if(!b){b=document.createElement('span');b.className='src-para-badge';el.appendChild(b);}b.textContent='✎ '+n;el.classList.add('annotated');}else{if(b)b.remove();el.classList.remove('annotated');}});}
function renderMain(){renderTitle();const p=selectedPaper();const surf=$('paperSurface');surf.innerHTML=!p?'<div class="archive-empty"><h2>尚未导入任何文献</h2><p>通过右上角导入每日 JSON，即可建立文献归档。</p></div>':state.mode==='analysis'?renderAnalysis(p):state.mode==='metadata'?renderMetadata(p):renderOriginal(p);
 document.querySelectorAll('.mode-tabs [data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));
 if(p&&state.mode==='original'){updatePdfPageUI();enhanceSourceReader(p);if(state.pdfView==='frame')loadLocalPdf(p).catch(()=>{});}
}
function renderMargins(){const p=selectedPaper(),el=$('marginList');if(!p){el.innerHTML='<div class="empty-mini">请选择文献。</div>';return;}
 const arr=marginFor(p.id);el.innerHTML=arr.length?arr.slice().reverse().map(m=>`<div class="margin-note" data-editmargin="${safe(m.id)}"><div class="mtop"><span>${safe({question:'❓ 疑问',method:'▧ 方法',insight:'✦ 启发',caution:'⚑ 质疑'}[m.kind]||'边注')}</span><span>${safe(m.locator||'未定位')}</span></div>${m.quote?`<blockquote>“${safe(cap(m.quote,150))}”</blockquote>`:''}<p>${safe(cap(m.comment,160))}</p></div>`).join(''):'<div class="empty-mini">暂无个人边注。<br>你可以选中文本或手动添加。</div>';
}
function setSave(text,saving=false){const e=$('saveState');e.textContent=text;e.classList.toggle('saving',saving);}
function renderNotes(){const p=selectedPaper();const n=p?noteFor(p.id):noteFor('__blank__');$('readingState').value=n.status||'unread';$('personalRating').value=n.rating||'';$('noteSummary').value=n.summary||'';$('noteMethods').value=n.methods||'';$('noteIdeas').value=n.ideas||''; $('revCount').textContent=(state.revisions[p?.id]||[]).length;
 document.querySelectorAll('.right-col textarea,.right-col select').forEach(el=>el.disabled=!p);
 setSave(n.updated?`● 已保存 ${n.updated.slice(11,16)}`:'● 尚未编辑');renderHistory();}
function renderHistory(){const p=selectedPaper(),arr=p?(state.revisions[p.id]||[]):[];const el=$('historyList');el.classList.toggle('hidden',!state.historyOpen);el.innerHTML=arr.length?arr.slice().reverse().map(r=>`<div class="revision-row"><span>${safe(r.date.slice(0,16).replace('T',' '))}<br><small>${safe(cap(r.note?.summary||r.note?.methods||'存档',38))}</small></span><button data-restore="${safe(r.id)}">恢复此版</button></div>`).join(''):'<div class="empty-mini">还没有手动保存的历史版本。</div>';}
function render(){renderArchive();renderMain();renderMargins();renderNotes();}
function collectNote(){return {summary:$('noteSummary').value,methods:$('noteMethods').value,ideas:$('noteIdeas').value,status:$('readingState').value,rating:$('personalRating').value,updated:stamp()};}
function commitNote(){const p=selectedPaper();if(!p)return;const n=collectNote();state.notes[p.id]=n;saveJSON('notes',state.notes);setSave(`● 已保存 ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`);}
function queueNoteSave(){setSave('● 保存中…',true);clearTimeout(saveTimer);saveTimer=setTimeout(()=>{commitNote();},420);}
function saveRevision(){const p=selectedPaper();if(!p)return toast('请先选择文献');commitNote();const arr=state.revisions[p.id]||(state.revisions[p.id]=[]);const date=stamp();arr.push({id:date+'_'+Math.random().toString(36).slice(2,6),date,note:JSON.parse(JSON.stringify(state.notes[p.id]))});if(saveJSON('revisions',state.revisions)){state.historyOpen=true;renderHistory();$('revCount').textContent=arr.length;toast('笔记快照已保存，可随时恢复。');}}
function openMargin(m=null,quote='',locator=''){const p=selectedPaper();if(!p)return toast('请先选择文献');state.editingMargin=m?.id||null;$('quoteField').value=m?.quote||quote||'';$('locatorField').value=m?.locator||locator||'';$('marginComment').value=m?.comment||'';$('marginKind').value=m?.kind||'question';$('deleteMargin').classList.toggle('hidden',!m);$('marginModal').classList.remove('hidden');$('marginComment').focus();}
function closeMargin(){$('marginModal').classList.add('hidden');state.editingMargin=null;}
function saveMargin(){const p=selectedPaper();if(!p)return;const quote=$('quoteField').value.trim(),comment=$('marginComment').value.trim();if(!quote&&!comment)return toast('请输入引用或批注内容');const arr=state.margins[p.id]||(state.margins[p.id]=[]);const now=stamp(),m={id:state.editingMargin||now+'_'+Math.random().toString(36).slice(2,8),quote,comment,locator:$('locatorField').value.trim(),kind:$('marginKind').value,updated:now};if(state.editingMargin){const pos=arr.findIndex(x=>x.id===state.editingMargin);if(pos>=0)arr[pos]=m;else arr.push(m);}else arr.push(m);saveJSON('margins',state.margins);renderMargins();updatePdfPageUI();refreshSrcBadges();closeMargin();toast('边注已保存到本机。');}
function deleteMargin(){const p=selectedPaper();if(!p||!state.editingMargin)return;state.margins[p.id]=marginFor(p.id).filter(m=>m.id!==state.editingMargin);saveJSON('margins',state.margins);closeMargin();renderMargins();updatePdfPageUI();refreshSrcBadges();toast('边注已删除。');}
function setMode(mode){commitNote();state.mode=mode;renderMain();$('centerCol').scrollTop=0;}
function selectionQuote(){const s=window.getSelection();if(!s||s.isCollapsed)return '';const t=s.toString().trim();if(!t)return '';const node=s.anchorNode?.parentElement;const el=node?.closest('[data-selectable]');return el&&$('paperSurface').contains(el)?t.slice(0,3000):'';}
function download(name,content,type='application/json'){const b=new Blob([content],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function exportBackup(){commitNote();const data={format:'archaea_reader_backup',version:1,exported_at:stamp(),issues:state.issueData,notes:state.notes,margins:state.margins,revisions:state.revisions,pdfMeta:state.pdfMeta,disclaimer:'PDF文件二进制未包含在此备份中，请单独保存本地PDF。'};download('archaea-完整归档与批注-'+new Date().toISOString().slice(0,10)+'.json','\uFEFF'+JSON.stringify(data,null,2),'application/json;charset=utf-8');toast('已导出完整 JSON 备份：归档、个人笔记、边注和历史版本。');}
function normalizeNewIssue(raw){if(!raw||!Array.isArray(raw.papers))throw Error('未找到 papers 数组');let issue=JSON.parse(JSON.stringify(raw));issue.issue_id=raw.issue_id||'manual-'+(raw.date||new Date().toISOString().slice(0,10));issue.date=raw.date||new Date().toISOString().slice(0,10);issue.issue_number=Number(raw.issue_number)||undefined;issue.papers=raw.papers.map((p,i)=>{
  let d=String(p.doi||'').trim().replace(/^https?:\/\/doi.org\//i,'').toLowerCase(); const get=(...ks)=>{for(const k of ks)if(p[k]!=null&&p[k]!=='')return Array.isArray(p[k])?p[k].join('、'):String(p[k]);return '';};
  return {id:d||issue.issue_id+'-'+i,doi:d,title:get('title'),authors:p.authors||[],journal:get('journal','venue'),date:get('first_published','publication_date'),kind:get('publication_type','type'),priority:get('priority','learning_priority')||'A',url:get('publisher_url','url')||doiUrl(d),reading_status:get('reading_status'),topic:Array.isArray(p.categories)?p.categories:(Array.isArray(p.category)?p.category:((p.categories||p.category)?[p.categories||p.category]:[])),question:get('research_question','question'),materials:get('materials'),design:get('study_design','design_methods','design'),methods:get('methods'),results:get('key_findings','findings','results'),innovation:get('methodological_innovation','innovation'),limitations:get('limitations'),future:get('future_value','future'),learning:get('learning','learning_priority'),verification:get('verification','metadata_verified_via'),notice:'用户导入内容；请通过官方 DOI 登记与期刊核验后引用。',source_issue:issue.issue_id};
 });return issue;}
function addIssues(issues){let count=0,changed=0;for(let issue of issues){const old=state.issueData.find(x=>x.issue_id===issue.issue_id);if(old){const canon=v=>JSON.stringify(v,(k,val)=>val&&typeof val==='object'&&!Array.isArray(val)?Object.fromEntries(Object.keys(val).sort().map(x=>[x,val[x]])):val);const fingerprint=o=>canon(o.papers??[]);if(fingerprint(old)===fingerprint(issue))continue;const orig=old.issue_id;const versions=state.issueData.filter(x=>x.issue_id===orig||x.issue_id.startsWith(orig+'-v'));const v=versions.length+1;issue.issue_id=orig+'-v'+v;issue.version_of=orig;issue.version=v;changed++;}
 state.issueData.push(issue);count++;}
 if(count){saveJSON('issues',state.issueData);const last=state.issueData.at(-1);if(last?.papers?.length){state.selected=last.papers[0].id;state.issue=last.issue_id;}render();toast(`已导入 ${count} 期，其中 ${changed} 期作为新版本保存；旧版本没有覆盖。`);}else toast('没有新增内容：导入文件与现有归档相同。');}
async function importFiles(files){let chunks=[],notesImported=0;for(const f of [...files]){let d;try{d=JSON.parse((await f.text()).replace(/^\uFEFF/,''))}catch(e){toast(f.name+' 不是有效JSON');continue;}if(d.format==='archaea_reader_backup'){
   // Preserve all previous versions, merge notes only if newer to avoid silent overwrite
   for(const [k,n] of Object.entries(d.notes||{})){const old=state.notes[k];if(!old||String(n.updated||'')>String(old.updated||'')){state.notes[k]=n;notesImported++;}}
   for(const [k,arr] of Object.entries(d.margins||{})){const map=new Map([...(state.margins[k]||[]),...arr].map(x=>[x.id,x]));state.margins[k]=[...map.values()];}
   for(const [k,arr] of Object.entries(d.revisions||{})){const map=new Map([...(state.revisions[k]||[]),...arr].map(x=>[x.id,x]));state.revisions[k]=[...map.values()];}
   chunks.push(...(d.issues||[]));
 }else if(Array.isArray(d.issues)){chunks.push(...d.issues.map(i=>(i.papers?.[0]?.id!==undefined?i:normalizeNewIssue(i))));}
 else if(Array.isArray(d.papers)){chunks.push(normalizeNewIssue(d));}else toast(f.name+' 缺少可识别的 issues 或 papers 数组');}
 saveJSON('notes',state.notes);saveJSON('margins',state.margins);saveJSON('revisions',state.revisions);if(chunks.length)addIssues(chunks);else render();if(notesImported)toast('已合并 '+notesImported+' 条个人笔记，未覆盖较新的版本。');$('importInput').value='';}
const ISSUE_TITLE='古DNA与生物考古文献精选';
const RESEARCH_SECTIONS=[['研究问题','question'],['研究材料','materials'],['实验设计','design'],['方法流程','methods'],['主要结果','results'],['方法学创新','innovation'],['局限与竞争解释','limitations'],['后续价值','future'],['学习重点','learning']];
const STATUS_LABELS={unread:'待读',reading:'阅读中',reviewed:'已精读',revisit:'待复核'};
const MARGIN_LABELS={question:'疑问',method:'方法',insight:'启发',caution:'质疑'};
/* ---------- 整段翻译与词汇简析：本地优先，不默认上传原文 ---------- */
const LEXICON=window.ARCHAEA_LEXICON||{domain:[],exam:[],morph:[]};
const DOMAIN_LEX=new Map((LEXICON.domain||[]).map(([w,pos,zh,note])=>[String(w).toLowerCase(),{type:'prof',pos,zh,note}]));
const EXAM_LEX=new Map((LEXICON.exam||[]).map(([w,level,pos,zh,note])=>[String(w).toLowerCase(),{type:'exam',level,pos,zh,note}]));
const MORPH_PREFIX=(LEXICON.morph||[]).filter(m=>m[1]==='pre').map(m=>[String(m[0]).toLowerCase(),m[2]]).sort((a,b)=>b[0].length-a[0].length);
const MORPH_SUFFIX=(LEXICON.morph||[]).filter(m=>m[1]==='suf').map(m=>[String(m[0]).toLowerCase(),m[2]]).sort((a,b)=>b[0].length-a[0].length);
const STOPWORDS=new Set(('a an the and or but if then than that this these those there their they them we our you your he she his her it its of to in on at for from by with without as such not no nor so very can could may might must should would will shall do does did done has have had having is are was were be been being also more most less least other another some any each both few many much own same only just about into over after before between during under above below up down out off again further once here when where why how all either neither while because although though since until unless whether which who whom whose what whatever however therefore thus hence moreover furthermore besides instead rather already still yet even ever never always often sometimes usually according based due related compared respectively approximately estimated including reported observed found shown used using known called considered seen made given taken et al fig figure table supplementary data result results method methods study studies background objective conclusion conclusions aim aims introduction discussion sample samples').split(/\s+/).filter(Boolean));
const IRREGULAR={analyses:'analysis',hypotheses:'hypothesis',phenomena:'phenomenon',criteria:'criterion',taxa:'taxon',genera:'genus',nuclei:'nucleus',teeth:'tooth',data:'data',species:'species',stimuli:'stimulus',loci:'locus',vertebrae:'vertebra'};
const SPELLING={analyse:'analyze',analysed:'analyzed',analysing:'analyzing',behaviour:'behavior',colour:'color',favour:'favor',labour:'labor',centre:'center',metre:'meter',fibre:'fiber',defence:'defense',licence:'license',programme:'program',catalogue:'catalog'};
let localTranslator=null;
function canonicalWord(w){if(IRREGULAR[w])return IRREGULAR[w];if(SPELLING[w])return SPELLING[w];if(/ies$/.test(w)&&w.length>4)return w.slice(0,-3)+'y';if(/(ses|xes|zes|ches|shes)$/.test(w))return w.slice(0,-2);if(/s$/.test(w)&&!/(ss|us|is)$/.test(w)&&w.length>3)return w.slice(0,-1);if(/ing$/.test(w)&&w.length>5)return w.slice(0,-3);if(/ed$/.test(w)&&w.length>4)return w.slice(0,-2);return w;}
function lexLookup(w){const base=canonicalWord(w);const cands=[w,base,base+'e'];if(base.endsWith('e'))cands.push(base.slice(0,-1));for(const c of cands){if(DOMAIN_LEX.has(c))return {entry:DOMAIN_LEX.get(c),key:c};if(EXAM_LEX.has(c))return {entry:EXAM_LEX.get(c),key:c};}return null;}
function morphNotes(w){const notes=[];const p=MORPH_PREFIX.find(([m])=>w.startsWith(m)&&w.length-m.length>=3);if(p)notes.push(p[0]+'（'+p[1]+'）');const s=MORPH_SUFFIX.find(([m])=>w.endsWith(m)&&w.length-m.length>=3);if(s)notes.push(s[0]+'（'+s[1]+'）');return notes.join(' + ');}
function analyzeVocabulary(text){const words=String(text||'').match(/[A-Za-z][A-Za-z'’-]*/g)||[];const rows=new Map();for(const raw of words){const surface=raw.replace(/[’']s$/i,'').replace(/^[’'-]+|[’'-]+$/g,'');if(surface.length<3)continue;const low=surface.toLowerCase();if(STOPWORDS.has(low))continue;const hit=lexLookup(low);if(!hit&&/^[A-Z]/.test(surface.charAt(0)))continue;const entry=hit&&hit.entry;const key=hit?(entry.type==='prof'?'p:'+hit.key:'e:'+hit.key):'w:'+canonicalWord(low);const row=rows.get(key);if(row){row.count++;continue;}if(entry&&entry.type==='prof'){rows.set(key,{word:(hit?hit.key:canonicalWord(low)),count:1,tag:'专业',cls:'prof',pos:entry.pos,zh:entry.zh,note:entry.note||''});}else if(entry&&entry.type==='exam'){rows.set(key,{word:(hit?hit.key:canonicalWord(low)),count:1,tag:entry.level,cls:String(entry.level).toLowerCase(),pos:entry.pos,zh:entry.zh,note:entry.note||''});}else{const note=morphNotes(low);if(note)rows.set(key,{word:(hit?hit.key:canonicalWord(low)),count:1,tag:'构词',cls:'morph',pos:'',zh:'词素：'+note,note:''});else if(canonicalWord(low).length>=7)rows.set(key,{word:(hit?hit.key:canonicalWord(low)),count:1,tag:'未收录',cls:'none',pos:'',zh:'未收录；建议结合上下文或外部词典核对。',note:''});}}
const rank={prof:0,'专业':0,IELTS:1,CET6:2,CET4:3,morph:4,'构词':4,none:5,'未收录':5};return [...rows.values()].sort((a,b)=>(rank[a.tag]??9)-(rank[b.tag]??9)||b.count-a.count||a.word.localeCompare(b.word)).slice(0,120);}
function splitParagraphs(text){return String(text||'').replace(/\r\n?/g,'\n').split(/\n\s*\n+/).map(s=>s.trim()).filter(Boolean);}
function chunkText(text,max){const s=String(text||'');if(s.length<=max)return [s];const parts=[];let buf='';const sentences=s.match(/[^.!?;]+[.!?;]?\s*/g)||[s];for(const sent of sentences){if((buf+sent).length>max){if(buf.trim())parts.push(buf.trim());buf='';}if(sent.length>max){for(let i=0;i<sent.length;i+=max)parts.push(sent.slice(i,i+max));}else{buf+=sent;}}if(buf.trim())parts.push(buf.trim());return parts.filter(Boolean);}
function trSetStatus(msg,isError){const el=$('trStatus');if(!el)return;el.textContent=msg||'';el.classList.toggle('error',!!isError);}
async function getLocalTranslator(){if(localTranslator)return localTranslator;if(!window.Translator)return null;for(const targetLanguage of ['zh','zh-Hans']){try{if(window.Translator.availability){const a=await window.Translator.availability({sourceLanguage:'en',targetLanguage});if(a==='unavailable')continue;}localTranslator=await window.Translator.create({sourceLanguage:'en',targetLanguage,monitor(m){if(!m||!m.addEventListener)return;m.addEventListener('downloadprogress',e=>{try{if(e&&e.total)trSetStatus('正在下载本地语言模型 '+Math.round(e.loaded/e.total*100)+'%');}catch(err){}});}});if(localTranslator)return localTranslator;}catch(e){localTranslator=null;}}return null;}
function decodeEntities(s){return String(s||'').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/&#(\d+);/g,(m,d)=>String.fromCharCode(+d));}
async function gtxTranslate(text){const url='https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=zh-CN&dt=t&q='+encodeURIComponent(text);const r=await fetch(url);if(!r.ok)throw Error('Google HTTP '+r.status);const j=await r.json();if(!Array.isArray(j)||!Array.isArray(j[0]))throw Error('Google 返回格式异常');return j[0].map(x=>Array.isArray(x)?x[0]:'').join('');}
async function myMemoryTranslate(text){const url='https://api.mymemory.translated.net/get?q='+encodeURIComponent(text)+'&langpair=en|zh-CN';const r=await fetch(url);if(!r.ok)throw Error('MyMemory HTTP '+r.status);const j=await r.json();if(j.responseStatus&&Number(j.responseStatus)!==200)throw Error(j.responseDetails||('MyMemory '+j.responseStatus));const t=j.responseData&&j.responseData.translatedText;if(!t)throw Error('MyMemory 未返回译文');return decodeEntities(t);}
async function remoteTranslate(text){const chunks=chunkText(text,420);const out=[];for(const c of chunks){let done=false;try{out.push(await gtxTranslate(c));done=true;}catch(e){}if(!done)out.push(await myMemoryTranslate(c));}return out.join('');}
async function runTranslation(){const p=selectedPaper();if(!p)return toast('请先选择文献');const ta=$('trSource');const text=ta?ta.value.trim():'';if(!text)return toast('请先粘贴英文段落，或载入本篇摘要');const cjk=(text.match(/[\u4e00-\u9fff]/g)||[]).length;if(cjk>text.length*0.4)return toast('这段文字以中文为主，请粘贴英文原文');const btn=$('trRun');if(btn){btn.disabled=true;btn.textContent='翻译中…';}trSetStatus('正在准备翻译引擎…');const started=Date.now();try{const paras=splitParagraphs(text);const local=await getLocalTranslator();const engine=local?'浏览器内置翻译（本地）':'在线翻译（Google / MyMemory）';if(!local)trSetStatus('本地翻译不可用，改用在线接口…');const results=[];let done=0;for(const para of paras){const pieces=chunkText(para,2500);const outs=[];for(const piece of pieces){try{outs.push(local?await local.translate(piece):await remoteTranslate(piece));}catch(e){if(!local)throw e;outs.push(await remoteTranslate(piece));}}results.push({src:para,out:outs.join('')});done++;if(paras.length>1)trSetStatus('已翻译 '+done+'/'+paras.length+' 段…');}const vocab=analyzeVocabulary(text);state.tr[p.id]={source:text,paragraphs:results,vocab,engine,at:stamp()};const out=$('trOutput');if(out){out.innerHTML=trResultHTML(state.tr[p.id]);if(out.scrollIntoView)out.scrollIntoView({block:'nearest'});}trSetStatus('完成：'+results.length+' 段 · '+vocab.length+' 个词汇候选 · 用时 '+((Date.now()-started)/1000).toFixed(1)+' 秒。');}catch(e){trSetStatus('翻译失败：'+(e&&e.message?e.message:e)+'。请检查网络，或改用支持内置翻译的 Chrome。',true);}finally{if(btn){btn.disabled=false;btn.textContent='译 · 翻译并分析词汇';}}}
function abstractFromInverted(inv){const arr=[];Object.keys(inv||{}).forEach(w=>{(inv[w]||[]).forEach(pos=>{arr[pos]=w;});});return arr.filter(Boolean).join(' ');}
function stripJats(html){const s=String(html||'');try{const d=new DOMParser().parseFromString(s,'text/html');return (d.body.textContent||'').replace(/\s+/g,' ').trim();}catch(e){return s.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}}
async function loadPaperAbstract(){const p=selectedPaper();if(!p)return;if(!p.doi)return toast('本篇没有 DOI，无法自动获取摘要，请手动粘贴');trSetStatus('正在从 OpenAlex / Crossref 获取英文摘要…');const text=await fetchPaperAbstract(p);if(!text){trSetStatus('没有取到开放摘要（可能未开放或网络受限）。请从原文复制段落粘贴。',true);return;}const ta=$('trSource');if(ta)ta.value=text;const rec=state.tr[p.id]||(state.tr[p.id]={});rec.source=text;const count=$('trCount');if(count)count.textContent=text.length+' 字符';trSetStatus('已载入摘要（'+text.length+' 字符），点击「翻译并分析词汇」。');}
function fillFromSelection(){const s=window.getSelection();const t=s?s.toString().trim():'';if(!t||t.length<20)return toast('请先在页面上选中一段英文');const ta=$('trSource');if(!ta)return;ta.value=t;const p=selectedPaper();if(p){const rec=state.tr[p.id]||(state.tr[p.id]={});rec.source=t;}const c=$('trCount');if(c)c.textContent=t.length+' 字符';trSetStatus('已填入所选文本（'+t.length+' 字符）。');}
function trResultHTML(rec){if(!rec||!rec.paragraphs||!rec.paragraphs.length)return '';const vocab=rec.vocab||[];const counts={};vocab.forEach(v=>{counts[v.tag]=(counts[v.tag]||0)+1;});const summary=Object.keys(counts).map(k=>k+' '+counts[k]).join(' · ');return '<div class="tr-meta"><span>引擎：'+safe(rec.engine||'—')+'</span><span>'+rec.paragraphs.length+' 段</span><span>'+vocab.length+' 个词汇候选</span><span class="tr-meta-actions"><button class="bare-btn" id="trCopyText">复制译文</button><button class="bare-btn" id="trCopyVocab">复制词表</button></span></div><div class="tr-result">'+rec.paragraphs.map((x,i)=>'<div class="tr-block"><div class="tr-block-label">段落 '+(i+1)+'</div><p class="tr-target">'+safe(x.out)+'</p><details class="tr-original"><summary>查看英文原文</summary><p>'+safe(x.src)+'</p></details></div>').join('')+'</div><div class="vocab-head"><h3>词汇简析</h3><span class="vocab-sum">'+safe(summary)+'</span></div><div class="vocab-wrap"><table class="vocab-table"><thead><tr><th>词</th><th>标注</th><th>释义与简析</th></tr></thead><tbody>'+vocab.map(v=>'<tr><td class="vocab-word">'+safe(v.word)+(v.count>1?' <sup>×'+v.count+'</sup>':'')+'</td><td><span class="lv lv-'+safe(v.cls)+'">'+safe(v.tag)+'</span></td><td>'+(v.pos?'<em>'+safe(v.pos)+'</em> ':'')+safe(v.zh)+(v.note?'<span class="vocab-note">'+safe(v.note)+'</span>':'')+'</td></tr>').join('')+'</tbody></table></div>';}
function copyToClipboard(text,msg){const done=()=>toast(msg);if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(done).catch(()=>legacyCopy(text,done));}else legacyCopy(text,done);}
function legacyCopy(text,done){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');done();}catch(e){toast('复制失败，请手动选择文本');}ta.remove();}
function copyTranslation(){const p=selectedPaper();const rec=p&&state.tr[p.id];if(!rec)return toast('还没有译文');copyToClipboard(rec.paragraphs.map(x=>x.out).join('\n\n'),'译文已复制');}
function copyVocabulary(){const p=selectedPaper();const rec=p&&state.tr[p.id];if(!rec)return toast('还没有词表');copyToClipboard(rec.vocab.map(v=>v.word+'\t'+v.tag+'\t'+(v.pos||'')+'\t'+v.zh).join('\n'),'词表已复制');}
function renderTranslate(p){const rec=state.tr[p.id]||{};return '<div class="notice info">整段翻译优先使用<strong>浏览器内置翻译</strong>（Chrome 138+，在本机运行，不上传原文）；不可用时自动改用在线翻译接口。词汇简析来自内置参考词库（专业 / CET4 / CET6 / IELTS），难度为近似标注，专业释义请结合原文核对。</div><div class="tr-panel"><div class="tr-toolbar"><span class="tr-label">ENGLISH PASSAGE / 待翻译段落</span><span class="tr-count" id="trCount">'+safe(rec.source?rec.source.length+' 字符':'')+'</span></div><textarea id="trSource" spellcheck="false" placeholder="粘贴英文摘要或段落……也可以先点下方「载入本篇英文摘要」。">'+safe(rec.source||'')+'</textarea><div class="tr-actions"><button class="link-btn secondary" id="trLoadAbstract">↧ 载入本篇英文摘要</button><button class="link-btn secondary" id="trFromSelection">✎ 用选中的文本</button><button class="solid-btn tr-run" id="trRun">译 · 翻译并分析词汇</button></div><div class="tr-status" id="trStatus"></div></div><div id="trOutput" class="tr-output">'+(rec.paragraphs?trResultHTML(rec):'')+'</div>';}
function exportContext(){const p=selectedPaper();if(!p)return toast('请先选择文献'),null;const issue=state.issueData.find(i=>i.issue_id===p.__issue);if(!issue)return toast('找不到当前期次'),null;clearTimeout(saveTimer);saveTimer=null;commitNote();return {issue,p,n:noteFor(p.id),margins:marginFor(p.id)};}
function plainLine(value){return String(value??'').replace(/\s+/g,' ').trim();}
function mdText(value){return String(value??'').replace(/\r\n?/g,'\n').split('\n').map(line=>line.replace(/\\/g,'\\\\').replace(/([`*_{}\[\]<>|~])/g,'\\$1').replace(/^(\s{0,3})(#{1,6}\s|>\s?|[-+*]\s|\d+[.)]\s)/,(_,space,mark)=>space+'\\'+mark)).join('\n');}
function safeLink(value){try{const u=new URL(String(value||''));return ['https:','http:'].includes(u.protocol)?u.href:'';}catch(e){return '';}}
function mdLink(label,url){return url?`[${mdText(label)}](<${url.replace(/>/g,'%3E')}>)`:'未提供';}
function filePart(value){let name=plainLine(value).replace(/[<>:"/\\|?*\x00-\x1F]/g,'-').replace(/[. ]+$/g,'').slice(0,68).replace(/[. ]+$/g,'');if(!name||/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$/i.test(name))name='paper';return name;}
function markdownIssue(){const ctx=exportContext();if(!ctx)return;const {issue,p,n,margins}=ctx;const title=issue.title||ISSUE_TITLE,source=safeLink(p.url)||safeLink(p.doi?doiUrl(p.doi):''),doi=safeLink(p.doi?doiUrl(p.doi):'');let lines=[`# ${mdText(plainLine(title))}`,'',`- **期号**：${mdText(plainLine(issue.issue_id))}`,`- **日期**：${mdText(plainLine(issue.date))}`,'',`## ${mdText(plainLine(p.title||'未命名论文'))}`,'',`- **作者**：${mdText(plainLine(labels(p).authors))}`,`- **期刊 / 平台**：${mdText(plainLine(p.journal))}`,`- **发表日期**：${mdText(plainLine(p.date))}`,`- **文献类型**：${mdText(plainLine(p.kind))}`,`- **DOI**：${p.doi?mdLink(p.doi,doi):'未提供'}`,`- **来源链接**：${mdLink('打开来源',source)}`,`- **核读范围**：${mdText(plainLine(p.reading_status||'未记录'))}`,`- **书目核验**：${mdText(plainLine(p.verification||'未记录'))}`,`- **归档提示**：${mdText(plainLine(p.notice||'无'))}`,`- **我的阅读状态**：${mdText(STATUS_LABELS[n.status]||'待读')}`,`- **个人评级**：${mdText(n.rating||'未评级')}`,''];for(const [heading,key] of RESEARCH_SECTIONS){if(p[key])lines.push(`### ${heading}`,'',mdText(p[key]),'');}lines.push('## 我的研究笔记','',`### 研究摘要`,'',mdText(n.summary||'（暂无）'),'','### 方法与疑问','',mdText(n.methods||'（暂无）'),'','### 研究想法','',mdText(n.ideas||'（暂无）'),'','## 我的边注','');if(!margins.length)lines.push('（暂无）','');else margins.forEach((m,i)=>{lines.push(`### 边注 ${i+1} · ${MARGIN_LABELS[m.kind]||'边注'}`,'',`- **定位**：${mdText(plainLine(m.locator||'未定位'))}`,'',`**摘录**`,'',mdText(m.quote||'（无摘录）'),'','**批注**','',mdText(m.comment||'（无批注）'),'');});const filename=`ARCHAEA_${filePart(issue.issue_id)}_${filePart(p.title||p.doi)}.md`;download(filename,'\uFEFF'+lines.join('\n').trimEnd()+'\n','text/markdown;charset=utf-8');toast('已导出当前论文及笔记的 Markdown。');}
function printText(value){return safe(value||'（暂无）');}
function printSection(title,value){return value?`<section class="print-section"><h3>${safe(title)}</h3><div class="print-body">${safe(value)}</div></section>`:'';}
function preparePrint(ctx=exportContext()){if(!ctx)return false;const {issue,p,n,margins}=ctx;const title=issue.title||ISSUE_TITLE,source=safeLink(p.url)||safeLink(p.doi?doiUrl(p.doi):''),doi=safeLink(p.doi?doiUrl(p.doi):'');const row=(label,value)=>`<div class="print-meta-row"><strong>${safe(label)}</strong><span>${safe(value||'未提供')}</span></div>`;$('printSheet').innerHTML=`<header class="print-header"><div class="print-brand">ARCHAEA · 文献阅读台</div><h1>${safe(title)}</h1><p>${safe(issue.issue_id)} · ${safe(issue.date)}</p></header><h2>${safe(p.title||'未命名论文')}</h2><div class="print-meta">${row('作者',labels(p).authors)}${row('期刊 / 平台',p.journal)}${row('发表日期',p.date)}${row('文献类型',p.kind)}${row('DOI',p.doi)}${doi?`<div class="print-meta-row"><strong>DOI 链接</strong><a href="${safe(doi)}">${safe(doi)}</a></div>`:''}${source?`<div class="print-meta-row"><strong>来源链接</strong><a href="${safe(source)}">${safe(source)}</a></div>`:''}${row('核读范围',p.reading_status||'未记录')}${row('书目核验',p.verification||'未记录')}${row('归档提示',p.notice||'无')}${row('我的阅读状态',STATUS_LABELS[n.status]||'待读')}${row('个人评级',n.rating||'未评级')}</div><div class="print-research">${RESEARCH_SECTIONS.map(([heading,key])=>printSection(heading,p[key])).join('')}</div><section class="print-personal"><h2>我的研究笔记</h2>${printSection('研究摘要',n.summary||'（暂无）')}${printSection('方法与疑问',n.methods||'（暂无）')}${printSection('研究想法',n.ideas||'（暂无）')}</section><section class="print-personal"><h2>我的边注</h2>${margins.length?margins.map((m,i)=>`<section class="print-margin"><h3>边注 ${i+1} · ${safe(MARGIN_LABELS[m.kind]||'边注')} · ${safe(m.locator||'未定位')}</h3><div class="print-body"><strong>摘录</strong><br>${printText(m.quote)}<br><strong>批注</strong><br>${printText(m.comment)}</div></section>`).join(''):'<p>（暂无）</p>'}</section>`;return true;}
function printSelected(){if(preparePrint())window.print();}
async function verifyDOI(){const p=selectedPaper();if(!p?.doi)return;const el=$('verificationResult');el.innerHTML='<div class="reader-loader">正在查询 Crossref / DataCite 官方登记…</div>';let rec=null,source='';try{let r=await fetch('https://api.crossref.org/works/'+encodeURIComponent(p.doi),{headers:{Accept:'application/json'}});if(r.ok){rec=(await r.json()).message;source='Crossref';}}catch(e){}
 if(!rec)try{const r=await fetch('https://api.datacite.org/dois/'+encodeURIComponent(p.doi));if(r.ok){const a=(await r.json()).data.attributes;rec={title:[a.titles?.[0]?.title||''],author:(a.creators||[]).map(x=>({givenName:x.givenName,family:x.family,name:x.name})),published:{'date-parts':[[a.publicationYear]]},type:a.types?.resourceTypeGeneral};source='DataCite';}}catch(e){}
 if(!rec){el.innerHTML='<div class="notice">无法从当前浏览器读取登记接口，可能是跨域、网络或访问限制。可使用 DOI 官方页面手动核对。</div>';return;}
 const official=rec.title?.[0]||'',normalized=s=>String(s).toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');const same=normalized(official)===normalized(p.title),date=rec.published?.['date-parts']?.[0]?.join('-')||'未提供';el.innerHTML=`<div class="notice ${same?'info':''}">登记机构：${safe(source)}<br>登记标题：${safe(official)}<br>登记日期字段：${safe(date)}<br>标题比较：<strong>${same?'✓ 字符串一致':'⚠ 与本地归档不完全相同，需人工复核'}</strong><br><small>此检查不等于自动核实全部作者、首发日期、论文全文或同行评审状态。</small></div>`;
}
// OA PDF resolution: only look up an openly available PDF, do not proxy/copy protected publisher contents
async function findOpenAccess(){const p=selectedPaper();if(!p?.doi)return;const status=$('originalStatus');status.textContent='正在查询 OpenAlex 的合法开放获取位置…';try{const endpoint='https://api.openalex.org/works/https://doi.org/'+encodeURI(p.doi);const r=await fetch(endpoint,{headers:{Accept:'application/json'}});if(!r.ok)throw Error('OpenAlex HTTP '+r.status);const data=await r.json();const locations=[data.best_oa_location,...(data.locations||[])].filter(Boolean);const pdf=locations.map(x=>x.pdf_url).find(x=>/^https?:\/\//i.test(x||''));const landing=locations.map(x=>x.landing_page_url).find(x=>/^https?:\/\//i.test(x||''));if(pdf){state.pdfView='frame';renderPdfUrl(pdf,'开放获取 PDF','oa');renderMain();const st=$('originalStatus');if(st)st.textContent='已找到开放 PDF，正在尝试直接解析文字…';try{const resp=await fetch(pdf,{mode:'cors'});if(!resp.ok)throw Error('HTTP '+resp.status);const buf=await resp.arrayBuffer();await extractAndShowPdf(p,buf,'开放获取 PDF');}catch(err){const st2=$('originalStatus');if(st2)st2.textContent='已找到开放 PDF，但浏览器无法直接读取（跨域或网络限制）。可用「载入本机 PDF」导入后自动解析。';}}
 else{status.textContent='OpenAlex 暂未提供可直接嵌入的开放获取 PDF。可从出版页面阅读，或上传已合法获得的 PDF。';$('originalFrame').innerHTML=`<div class="blank-frame"><div><strong>暂无可嵌入 PDF</strong>找到的开放入口：${landing?`<a href="${safe(landing)}" target="_blank" rel="noopener noreferrer">打开开放页面 ↗</a>`:'无'}<br>请使用 DOI 或导入本机 PDF。</div></div>`;}
 }catch(e){status.textContent='当前无法连接 OpenAlex：'+e.message+'。可以点击 DOI，或上传本机 PDF。';}}
function renderPdfUrl(url,label,origin='remote'){state.readerUrl=url;state.pdfPage=1;const el=$('originalFrame');el.innerHTML=`<iframe class="pdf-frame" src="${safe(url)}" title="${safe(label)}" referrerpolicy="no-referrer"></iframe><div class="link-row"><a class="link-btn" href="${safe(url)}" target="_blank" rel="noopener noreferrer">↗ 单独打开 ${safe(label)}</a></div><div class="original-hint">提示：某些开放 PDF 服务器禁止第三方网站嵌入。此时 iframe 可能空白，但单独打开链接通常仍可访问。</div>`;const bar=$('pdfPageBar');if(bar)bar.classList.remove('hidden');updatePdfPageUI();}
// Store uploaded PDFs in IndexedDB on the same device. PDF bytes are not part of JSON backups.
function pdfDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('此浏览器不支持 IndexedDB'));const req=indexedDB.open('archaea-papers',1);req.onupgradeneeded=e=>{const db=e.target.result;if(!db.objectStoreNames.contains('pdfs'))db.createObjectStore('pdfs');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function saveLocalPdf(p,file){const db=await pdfDB();await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').put(file,p.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();state.pdfMeta[p.id]={name:file.name,size:file.size,saved:stamp()};saveJSON('pdfmeta',state.pdfMeta);toast('本机 PDF 已导入当前浏览器，仅在本设备可用。');await loadLocalPdf(p);}
async function loadLocalPdf(p){if(!p||state.mode!=='original')return;const db=await pdfDB();const blob=await new Promise((resolve,reject)=>{const req=db.transaction('pdfs','readonly').objectStore('pdfs').get(p.id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();if(blob){const u=URL.createObjectURL(blob);if(state.readerUrl?.startsWith('blob:'))URL.revokeObjectURL(state.readerUrl);renderPdfUrl(u,state.pdfMeta[p.id]?.name||'本机PDF','local');$('originalStatus').textContent='已加载本机 PDF：'+(state.pdfMeta[p.id]?.name||'未命名文件')+'。文件保存在当前设备的浏览器存储中。';}}
function setMobile(which){state.mobile=which;setNotesPanel(false);document.querySelector('.app').classList.remove('mobile-archive','mobile-reader','mobile-notes');document.querySelector('.app').classList.add('mobile-'+which);document.querySelectorAll('[data-mobile]').forEach(x=>x.classList.toggle('active',x.dataset.mobile===which));}
function setNotesPanel(open){const appEl=document.querySelector('.app');appEl.classList.toggle('notes-open',!!open);const tab=$('notesTab');if(tab){tab.classList.toggle('active',!!open);tab.setAttribute('aria-expanded',String(!!open));}}
function toggleNotesPanel(){setNotesPanel(!document.querySelector('.app').classList.contains('notes-open'));}
function initEvents(){
 $('archiveList').addEventListener('click',e=>{const b=e.target.closest('[data-select]');if(b)activatePaper(b.dataset.select,b.dataset.issue);});
 $('searchInput').addEventListener('input',e=>{state.search=e.target.value;renderArchive();});$('clearSearch').onclick=()=>{$('searchInput').value='';state.search='';renderArchive();};$('dateSortBtn').onclick=()=>{state.newest=!state.newest;$('dateSortBtn').textContent=state.newest?'日期 ↓':'日期 ↑';renderArchive();};
 document.querySelectorAll('.mode-tabs [data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
 $('addQuoteFromSelection').onclick=()=>{const q=selectionQuote()||lastSelection;openMargin(null,q);};
 $('paperSurface').addEventListener('mouseup',()=>{lastSelection=selectionQuote()||lastSelection;});
 $('newMarginNote').onclick=()=>openMargin();$('marginList').addEventListener('click',e=>{const item=e.target.closest('[data-editmargin]');const p=selectedPaper();if(item&&p){const m=marginFor(p.id).find(x=>x.id===item.dataset.editmargin);if(m)openMargin(m);}});
 $('closeModal').onclick=closeMargin;$('cancelModal').onclick=closeMargin;$('submitMargin').onclick=saveMargin;$('deleteMargin').onclick=deleteMargin;$('marginModal').onclick=e=>{if(e.target.id==='marginModal')closeMargin();};
 $('readingState').onchange=queueNoteSave;$('personalRating').onchange=queueNoteSave;['noteSummary','noteMethods','noteIdeas'].forEach(id=>$(id).addEventListener('input',queueNoteSave));
 $('saveRevision').onclick=saveRevision;$('showHistory').onclick=()=>{state.historyOpen=!state.historyOpen;renderHistory();};$('historyList').addEventListener('click',e=>{const b=e.target.closest('[data-restore]'),p=selectedPaper();if(!b||!p)return;const rev=(state.revisions[p.id]||[]).find(x=>x.id===b.dataset.restore);if(rev){if(!confirm('将此旧版的内容恢复到当前编辑框？恢复前会自动保留当前笔记快照。'))return;saveRevision();state.notes[p.id]=JSON.parse(JSON.stringify(rev.note));saveJSON('notes',state.notes);renderNotes();toast('已恢复历史版本；恢复前的笔记也已保存。');}});
 $('importBtn').onclick=()=>$('importInput').click();$('importInput').onchange=e=>importFiles(e.target.files);$('exportBtn').onclick=markdownIssue;$('printBtn').onclick=printSelected;$('backupBtn').onclick=exportBackup;
 $('paperSurface').addEventListener('click',async e=>{const t=e.target.closest('button');const para=e.target.closest('.src-para[data-src-index]');if(para&&!t){const b=para.querySelector('[data-annotate]');if(b){toggleSourceComposer(b);return;}}if(!t)return;const p=selectedPaper();if(t.dataset.annotate!==undefined){toggleSourceComposer(t);return;}if(t.dataset.saveAnnotation!==undefined){saveInlineAnnotation(p,Number(t.dataset.saveAnnotation));return;}if(t.dataset.cancelAnnotation!==undefined){hideSourceComposer(t);return;}if(t.dataset.delAnnotation){deleteInlineMargin(p,t.dataset.delAnnotation);return;}if(t.matches('[data-tr-save]')){saveReaderSettings();return;}const pageBtn=e.target.closest('[data-pdfpage]');if(pageBtn){pdfGo(Number(pageBtn.dataset.pdfpage));return;}switch(t.id){case 'findOA':await findOpenAccess();break;case 'localPdfBtn':$('pdfInput').click();break;case 'togglePdfView':state.pdfView=state.pdfView==='frame'?'text':'frame';if(state.pdfView==='frame')loadLocalPdf(p).catch(()=>{});renderMain();break;case 'addPdfQuoteBtn':openMargin();break;case 'verifyDoiBtn':await verifyDOI();break;case 'issueExportBtn':markdownIssue();break;case 'trRun':await runTranslation();break;case 'trLoadAbstract':await loadPaperAbstract();break;case 'trFromSelection':fillFromSelection();break;case 'trCopyText':copyTranslation();break;case 'trCopyVocab':copyVocabulary();break;case 'annotatePdfPage':annotatePdfPage();break;case 'loadSrcAbstract':await loadSourceAbstract();break;case 'showSrcPaste':toggleSrcPaste();break;case 'segmentSrc':segmentSrcText();break;case 'cancelSrcPaste':toggleSrcPaste(false);break;}});
 $('paperSurface').addEventListener('input',e=>{if(e.target&&e.target.id==='trSource'){const p=selectedPaper();if(p){const rec=state.tr[p.id]||(state.tr[p.id]={});rec.source=e.target.value;}const c=$('trCount');if(c)c.textContent=e.target.value.length+' 字符';}});
 $('paperSurface').addEventListener('paste',e=>{if(e.target&&e.target.id==='srcPaste'){setTimeout(()=>{const ta=$('srcPaste');if(ta&&ta.value.trim().length>40)segmentSrcText();},60);}});
 $('paperSurface').addEventListener('keydown',e=>{if(e.target&&e.target.id==='srcPaste'&&(e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();segmentSrcText();}});
 $('paperSurface').addEventListener('change',e=>{if(e.target.matches('[data-tr-engine]')){const box=e.target.closest('.src-settings');const api=box&&box.querySelector('[data-tr-api]');if(api)api.classList.toggle('hidden',e.target.value!=='api');}});
 $('pdfInput').onchange=async e=>{const f=e.target.files?.[0],p=selectedPaper();if(f&&p){if(f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf'))return toast('请选择 PDF 文件');try{const buf=await f.arrayBuffer();state.pdfView='frame';await saveLocalPdf(p,f);await extractAndShowPdf(p,buf,f.name);}catch(err){toast('无法处理 PDF：'+(err&&err.message?err.message:err));}}$('pdfInput').value='';};
 document.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>setMobile(b.dataset.mobile));$('notesTab').onclick=toggleNotesPanel;
 window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMargin();setNotesPanel(false);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveRevision();}});
 window.addEventListener('beforeprint',()=>{preparePrint();});window.addEventListener('afterprint',()=>{$('printSheet').innerHTML='';});
 window.addEventListener('beforeunload',()=>{if(saveTimer)commitNote();});
}
function boot(){const active=loadJSON('active',null);const all=paperList();let found=active&&all.find(p=>p.id===active.id&&p.__issue===active.issue);if(!found)found=normalizedIssues().flatMap(i=>i.papers.map(p=>({...p,__issue:i.issue_id}))).at(0);state.selected=found?.id||null;state.issue=found?.__issue||null;initEvents();render();setMobile('reader');}
boot();
})();
